"""Publication includes only outputs regenerated by this refresh."""
from contextlib import redirect_stdout
import io
import json
from pathlib import Path
import sys
import tempfile
from types import SimpleNamespace
import unittest

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from refresh_db2_data import prepare_manifest


class ManifestTest(unittest.TestCase):
    def test_superseded_and_unrelated_cache_files_are_not_published(self):
        with tempfile.TemporaryDirectory() as directory:
            base = Path(directory)
            output = base / 'output'
            build = '12.1.5.70391'
            (output / 'db2' / build).mkdir(parents=True)
            root = output / 'client-data'
            (root / 'cache').mkdir(parents=True)
            current = root / 'cache/spell_catalog-active.bin'
            current.write_bytes(b'current source')
            (root / 'cache/spell_visuals-12.1.5.70340-v13.bin').write_bytes(b'previous source')
            (root / 'cache/npc_appearance.sqlite').write_bytes(b'unrelated TDB catalog')
            (output / 'cache-import.log').write_text(str(current) + '\n')
            args = SimpleNamespace(output=output, canonical_engine=base / 'engine', canonical_server=base / 'server')
            receipt = {'identity': {'build': build}, 'schema_commit': 'pinned'}
            with redirect_stdout(io.StringIO()):
                prepare_manifest(args, receipt, root)
            manifest = json.loads((output / 'apply-manifest.json').read_text())
            self.assertEqual([Path(entry['source']).name for entry in manifest['files']], ['spell_catalog-active.bin'])


if __name__ == '__main__':
    unittest.main()
